 if(['growth','diagnosis'].includes(tool)){const saved=$('#saved-description')?.closest('section');if(saved)saved.classList.add('research-shared-deck');const section=$('#journey-start').closest('section'),actions=$('#journey-start').parentElement;advanced(section,[actions,$('#journey-progress')],'세부 조건·유닛 교체');const note=[...document.querySelectorAll('#journey-body>section')].find(node=>node.querySelector('h2')?.textContent==='계산 기준');fold(note,'계산 기준·가정 보기');}
