function run(){apply();if(!ready())return;if(['growth','diagnosis','stages'].includes(tool))selectedView='results';if(tool==='gems'){selectedView='compare';window.dispatchEvent(new Event('stack-lab:research-run'));}else {if(tool==='guides'){selectedView='write';compactViews();}main()?.click();}schedule();}
function cancel(){if(tool==='gems')window.dispatchEvent(new Event('stack-lab:research-cancel'));else for(const selector of tool==='board'?['#compose-cancel','#cancel-giant']:tool==='stages'?['#cancel-stages']:['#journey-cancel'])if(shown(selector)){$(selector).click();break;}schedule();}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent||event.data?.channel!==channel)return;const data=event.data;if(data.context)context=data.context;if(data.type==='run')run();else if(data.type==='cancel')cancel();else if(data.type==='refresh'){if(!busy()){applying=true;try{refreshDeck();lastSaved=readSaved();applied='';}finally{applying=false;}}}schedule();});
