 const grid=picker.querySelector('.research-gem-grid'),search=picker.querySelector('input'),label=select.getAttribute('aria-label');search.value='';const options=[...select.options];const render=()=>{grid.replaceChildren();for(const option of options.filter(option=>option.textContent.toLowerCase().includes(search.value.toLowerCase()))){const button=el('button'),gem=CoopData.GEM_BY_ID.get(option.value),icon=el('span',undefined,'research-picker-icon');button.type='button';button.setAttribute('aria-pressed',String(select.value===option.value));if(gem)icon.style.backgroundImage='url("/assets/gems/'+gem.id+'.webp"),url("/assets/gems/stone-sss.webp")';else icon.textContent='−';button.append(icon,el('span',option.textContent));button.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));picker.close();requestAnimationFrame(()=>requestAnimationFrame(()=>[...document.querySelectorAll('.research-gem-trigger')].find(button=>button.dataset.for===label)?.focus({preventScroll:true})));};grid.append(button);}};search.oninput=render;render();picker.showModal();search.focus();
