 for(const [id,,nodes]of groups)for(const node of nodes){const hide=id!==selectedView;if(hide&&!node.hasAttribute('data-view-hidden'))node.setAttribute('data-view-hidden','');else if(!hide&&node.hasAttribute('data-view-hidden'))node.removeAttribute('data-view-hidden');}
